n.exploreUrl:
@js:
var menus = [
    { title: "完本", url: "/full/{{page}}/", flexBasis: 1 },

    { title: "════ 排 行 ════", url: "", flexBasis: 1 },

    { title: "总点击", url: "/top/allvisit_{{page}}/", flexBasis: 0.2 },
    { title: "月点击", url: "/top/monthvisit_{{page}}/", flexBasis: 0.2 },
    { title: "周点击", url: "/top/weekvisit_{{page}}/", flexBasis: 0.2 },

    { title: "════ 分 类 ════", url: "", flexBasis: 1 },

    { title: "玄幻奇幻", url: "/sort/1_{{page}}/", flexBasis: 0.25 },
    { title: "武侠仙侠", url: "/sort/2_{{page}}/", flexBasis: 0.25 },
    { title: "都市言情", url: "/sort/3_{{page}}/", flexBasis: 0.25 },
    { title: "历史穿越", url: "/sort/4_{{page}}/", flexBasis: 0.25 },

    { title: "网游竞技", url: "/sort/5_{{page}}/", flexBasis: 0.25 },
    { title: "科幻灵异", url: "/sort/6_{{page}}/", flexBasis: 0.25 },
    { title: "恐怖惊悚", url: "/sort/7_{{page}}/", flexBasis: 0.25 },
    { title: "其他类型", url: "/sort/8_{{page}}/", flexBasis: 0.25 }
];

var result = [];
for (var i = 0; i < menus.length; i++) {
    var item = menus[i];
    var style = {
        layout_flexGrow: 1,
        layout_flexBasisPercent: item.flexBasis
    };

    result.push({
        title: item.title,
        url: item.url,
        style: style
    });
}

JSON.stringify(result);

ruleToc.nextTocUrl:
class.showpage@ul@li.-3@a@href
<js>
let list = [];
const maxPageUrl = String(result[0]);
const baseMatch = maxPageUrl.match(/(.*)_/);
const pageMatch = maxPageUrl.match(/_(\d+)\//);

if (baseMatch && pageMatch) {
    const basePath = baseMatch[1];
    const maxPageNum = parseInt(pageMatch[1]);

    if (maxPageNum > 2) {
        for (let pageIndex = 2; pageIndex <= maxPageNum; pageIndex++) {
            list.push(`${basePath}_${pageIndex}/`);
        }
    }
}
list;
</js>

